def type_in_type_group(item, type_group):
    if item is None:
        return type(None) in type_group or None in type_group
    return type(item) in type_group

def number_to_string(number, significant_digits, number_format_notation='f'):
    if number_format_notation not in number_formatting:
        raise ValueError("number_format_notation must be 'f' or 'e'")

    if isinstance(number, only_complex_number):
        real_part = number_to_string(number.real, significant_digits, number_format_notation)
        imag_part = number_to_string(number.imag, significant_digits, number_format_notation)
        return '{} + {}j'.format(real_part, imag_part)

    fmt = number_formatting[number_format_notation] % significant_digits
    return fmt.format(number)
